import{_ as s,o as e,c as n,ag as t}from"./chunks/framework.DUTPmUpA.js";const i="/_assets/hzOmlcA.Ca2FOnyX.png",p="/_assets/4CcOl0i.0vOB3C4o.png",r="/_assets/xkwdcRx.m2T3MipN.png",g=JSON.parse('{"title":"Способствовать","description":"","frontmatter":{"title":"Способствовать"},"headers":[],"relativePath":"contribute.md","filePath":"contribute.md"}'),l={name:"contribute.md"};function o(c,a,d,u,b,h){return e(),n("div",null,[...a[0]||(a[0]=[t('<p>нести свой вклад</p><h2 id="предложить-статью-на-github" tabindex="-1">Предложить статью на GitHub <a class="header-anchor" href="#предложить-статью-на-github" aria-label="Permalink to &quot;Предложить статью на GitHub&quot;">​</a></h2><p>Чтобы предложить новую статью, перейдите по адресу <a href="https://github.com/ModDota/moddota.github.io/tree/source/_articles" target="_blank" rel="noreferrer">/_articles directory of the ModDota GitHub</a>.</p><p>::: информация Для этого вам необходимо войти в свою учетную запись GitHub. :::</p><p>Затем нажмите кнопку «Создать файл», как указано: <img src="'+i+'" alt="Click the create new file button"></p><h3 id="наполните-свою-статью" tabindex="-1">Наполните свою статью <a class="header-anchor" href="#наполните-свою-статью" aria-label="Permalink to &quot;Наполните свою статью&quot;">​</a></h3><p>В новом окне файла вам необходимо добавить описательное имя файла и текст для вашей статьи:</p><p><img src="'+p+`" alt="Fill your article"></p><p>::: совет Вы можете использовать вкладку предварительного просмотра вверху, чтобы просмотреть статью! :::</p><h4 id="важно-обязательные-поля" tabindex="-1">ВАЖНО: Обязательные поля <a class="header-anchor" href="#важно-обязательные-поля" aria-label="Permalink to &quot;ВАЖНО: Обязательные поля&quot;">​</a></h4><p>Чтобы статья работала, необходимо заполнить несколько обязательных полей:</p><p>Во-первых, вам нужно установить имя файла. Выберите описательное имя, слова должны быть разделены <code>-</code> (без пробелов). <strong>Файл должен заканчиваться на .md!</strong></p><p>Во-вторых, вам нужно указать основную информацию о статье вверху, макет всегда один и тот же (включая тире):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yaml</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>title: &lt;Title of your article&gt; # Title of your article (required)</span></span>
<span class="line"><span>author: &lt;your name&gt; # Your name</span></span>
<span class="line"><span>steamId: &#39;&lt;your steam ID&gt;&#39; # Your steam ID to link to your steam profile</span></span>
<span class="line"><span>date: &lt;date&gt; # The date of writing</span></span>
<span class="line"><span>---</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Единственное обязательное поле — <code>title</code>, все остальные поля можно безопасно опустить.</p><h3 id="отправьте-статью-на-рассмотрение" tabindex="-1">Отправьте статью на рассмотрение <a class="header-anchor" href="#отправьте-статью-на-рассмотрение" aria-label="Permalink to &quot;Отправьте статью на рассмотрение&quot;">​</a></h3><p>Когда вы закончите, вам просто нужно добавить очень краткое описание только что созданного вами урока внизу страницы. Это отобразится в истории изменений веб-сайта. Как только вы закончите, нажмите зеленую кнопку «Предложить новый файл».</p><p><img src="`+r+`" alt="Submit your tutorial"></p><h3 id="обзор-статьи" tabindex="-1">Обзор статьи <a class="header-anchor" href="#обзор-статьи" aria-label="Permalink to &quot;Обзор статьи&quot;">​</a></h3><p>Кто-то проверит, не повреждена ли статья на веб-сайте и не отсутствует ли информация, вас могут попросить внести некоторые изменения перед добавлением страницы на веб-сайт.</p><p>Как только ваше руководство будет объединено, оно автоматически появится на веб-сайте.</p><h2 id="учебники-по-написанию" tabindex="-1">Учебники по написанию <a class="header-anchor" href="#учебники-по-написанию" aria-label="Permalink to &quot;Учебники по написанию&quot;">​</a></h2><p>Учебные пособия могут быть написаны на языке разметки Markdown с поддержкой некоторых дополнительных функций GitHub Flavored Markdown. Чтобы ознакомиться с синтаксисом, вы можете посетить <a href="https://commonmark.org/help/" target="_blank" rel="noreferrer">this page</a>.</p><p>Кроме того, этот веб-сайт поддерживает расширения уценки, предоставляемые <a href="https://vitepress.dev/guide/markdown" target="_blank" rel="noreferrer">VitePress</a>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua{2}</span></span>
<span class="line"><span>function foo()</span></span>
<span class="line"><span>  -- Highlighted line</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="изображения-и-видео" tabindex="-1">Изображения и видео <a class="header-anchor" href="#изображения-и-видео" aria-label="Permalink to &quot;Изображения и видео&quot;">​</a></h3><p>Все изображения и видео должны храниться локально в репозитории, а не по внешним URL-адресам.</p><ul><li><strong>Изображения:</strong> Поместите в папку <code>_articles/images/</code> и укажите <code>![alt text](/images/your-image.png)</code>. – <strong>Видео.</strong> Поместите файлы <code>.mp4</code> в папку <code>_articles/videos/</code> и используйте <code>&lt;StaticVideo path=&quot;/videos/your-video.mp4&quot; /&gt;</code>.</li></ul><p><strong>Чтобы добавить проигрыватель YouTube на страницу, используйте следующее:</strong></p><p>Чтобы встроить <a href="https://www.youtube.com/watch?v=GMvmdnNM6Sc:" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=GMvmdnNM6Sc:</a> Используйте <code>&lt;YouTube id=&quot;GMvmdnNM6Sc&quot; /&gt;</code></p><h3 id="заголовки" tabindex="-1">Заголовки <a class="header-anchor" href="#заголовки" aria-label="Permalink to &quot;Заголовки&quot;">​</a></h3><p>В VitePress [заголовки] Markdown получают дополнительное значение — они используются для создания контура «На этой странице», который вы можете увидеть в правой части статьи.</p><p>:::информация По умолчанию в структуре отображаются только заголовки уровней 2 (##) и 3 (###). :::</p><h2 id="использование-git-форка" tabindex="-1">Использование git-форка <a class="header-anchor" href="#использование-git-форка" aria-label="Permalink to &quot;Использование git-форка&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Advanced users only</p></div><p>This website is set up as a GitHub Pages project built with VitePress. Content is rendered automatically after each push to the <code>source</code> branch and published to the website.</p><p>You can simply fork or clone the repository to edit the files and submit a pull request to the main repository.</p><p>File structure is as follows:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.</span></span>
<span class="line"><span>_articles/              # Directory storing all articles as markdown files</span></span>
<span class="line"><span>  | index.md            # Homepage</span></span>
<span class="line"><span>  | contribute.md       # This page</span></span>
<span class="line"><span>  | images/             # Static images</span></span>
<span class="line"><span>  | videos/             # Static videos</span></span>
<span class="line"><span>  | ...</span></span>
<span class="line"><span>.vitepress/</span></span>
<span class="line"><span>  | config.mts          # VitePress configuration (sidebar, nav, etc.)</span></span>
<span class="line"><span>  | theme/              # Custom theme, components, and CSS</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div>`,39)])])}const v=s(l,[["render",o]]);export{g as __pageData,v as default};
